import 'package:flutter/material.dart';
import '../../services/api.dart';
class OperationsScreen extends StatefulWidget { const OperationsScreen({super.key,required this.api}); final ApiClient api; @override State<OperationsScreen> createState()=>_OperationsScreenState(); }
class _OperationsScreenState extends State<OperationsScreen>{int tab=0;dynamic data;String? error;bool loading=true;@override void initState(){super.initState();_load();}Future<void>_load()async{setState(()=>loading=true);try{data=await widget.api.get(tab==0?'/business/goals':tab==1?'/units/requests':'/dashboard/summary');error=null;}catch(e){error='$e';}if(mounted)setState(()=>loading=false);}@override Widget build(BuildContext c){final title=['Meu negócio e relatórios','Multiunidade','Relatórios'][tab];final children=<Widget>[Text(title,style:Theme.of(c).textTheme.headlineSmall),if(error!=null)Text(error!),const SizedBox(height:12)];if(tab==0){for(final barber in (data?['barbers'] as List? ?? const [])){children.add(ListTile(leading:const Icon(Icons.flag),title:Text('${barber['name']}'),subtitle:const Text('Meta mensal e desempenho')));}}else if(tab==1){for(final unit in (data as List? ?? const [])){children.add(Card(child:ListTile(title:Text('${unit['unit_name']}'),subtitle:Text('${unit['city']}/${unit['state']} · ${unit['status']}'))));}}else{children.addAll([Text('Faturamento: R\$ ${((data?['revenue']as num?)??0).toStringAsFixed(2)}'),Text('Agendamentos: ${data?['appointments']??0}'),Text('Finalizados: ${data?['completed']??0}')]);}return Column(children:[Padding(padding:const EdgeInsets.all(8),child:SegmentedButton<int>(segments:const[ButtonSegment(value:0,label:Text('Negócio')),ButtonSegment(value:1,label:Text('Unidades')),ButtonSegment(value:2,label:Text('Relatórios'))],selected:{tab},onSelectionChanged:(v){tab=v.first;_load();})),Expanded(child:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:children)))]);}}
